using System;using System.Security.Cryptography;using System.Web.Mvc;using FindIt.DAL;using FindIt.Models;namespace FindIt.Controllers{public class AccountController:Controller{UserRepository repo=new UserRepository();static string Hash(string p,byte[] salt=null){salt=salt??RandomBytes(16);using(var pb=new Rfc2898DeriveBytes(p,salt,150000)){var h=pb.GetBytes(32);return "PBKDF2$150000$"+Convert.ToBase64String(salt)+"$"+Convert.ToBase64String(h);}}static byte[] RandomBytes(int n){var b=new byte[n];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return b;}static bool Verify(string p,string stored){try{var s=stored.Split('$');if(s.Length!=4||s[0]!="PBKDF2")return false;using(var pb=new Rfc2898DeriveBytes(p,Convert.FromBase64String(s[2]),int.Parse(s[1]))){var a=pb.GetBytes(32);var b=Convert.FromBase64String(s[3]);int diff=a.Length^b.Length;for(int i=0;i<Math.Min(a.Length,b.Length);i++)diff|=a[i]^b[i];return diff==0;}}catch{return false;}}[HttpGet]public ActionResult Login(){return View();}[HttpPost,ValidateAntiForgeryToken]public ActionResult Login(LoginViewModel m){if(!ModelState.IsValid)return View(m);try{var u=repo.ByEmail(m.Email);if(u==null||!u.IsActive||!Verify(m.Password,u.PasswordHash)){ModelState.AddModelError("","Invalid credentials or inactive account.");return View(m);}Session["UserId"]=u.UserId;Session["Name"]=u.FullName;Session["Role"]=u.Role;return RedirectToAction(u.Role=="Admin"?"Index":"Dashboard",u.Role=="Admin"?"Admin":"Student");}catch{ModelState.AddModelError("","Unable to sign in. Database may not be configured.");return View(m);}}[HttpGet]public ActionResult Register(){return View();}[HttpPost,ValidateAntiForgeryToken]public ActionResult Register(RegisterViewModel m){if(!ModelState.IsValid)return View(m);try{if(!repo.Create(m,Hash(m.Password))){ModelState.AddModelError("Email","That email is already registered.");return View(m);}TempData["Message"]="Registration successful. Please sign in.";return RedirectToAction("Login");}catch{ModelState.AddModelError("","Registration failed. Please check database setup.");return View(m);}}public ActionResult Logout(){Session.Clear();Session.Abandon();return RedirectToAction("Index","Home");}}}